import { test, expect } from '@playwright/test';

test.describe('Login Form CAPTCHA', () => {
  const username = 'testUser';
  const password = 'wrongPassword';

  test.beforeEach(async ({ page }) => {
    await page.goto('/login');
  });

  test('should display CAPTCHA after 3 failed login attempts', async ({ page }) => {
    for (let i = 0; i < 3; i++) {
      await page.getByLabel('Username').fill(username);
      await page.getByLabel('Password').fill(password);
      await page.getByRole('button', { name: 'Login' }).click();
      await expect(page.getByText('Invalid username or password')).toBeVisible();
    }

    await page.getByLabel('Username').fill(username);
    await page.getByLabel('Password').fill(password);
    await page.getByRole('button', { name: 'Login' }).click();

    await expect(page.getByRole('img', { name: 'CAPTCHA' })).toBeVisible();
  });

  test('should not display CAPTCHA before 3 failed attempts', async ({ page }) => {
    await page.getByLabel('Username').fill(username);
    await page.getByLabel('Password').fill(password);
    await page.getByRole('button', { name: 'Login' }).click();
    await expect(page.getByText('Invalid username or password')).toBeVisible();

    await page.getByLabel('Username').fill(username);
    await page.getByLabel('Password').fill(password);
    await page.getByRole('button', { name: 'Login' }).click();
    await expect(page.getByText('Invalid username or password')).toBeVisible();

    await page.getByLabel('Username').fill(username);
    await page.getByLabel('Password').fill(password);
    await page.getByRole('button', { name: 'Login' }).click();
    await expect(page.getByRole('img', { name: 'CAPTCHA' })).not.toBeVisible();
  });
});
